def count_pairs(nums, target):
    num_to_index = {}
    count = 0
    for index, num in enumerate(nums):
        complement = target - num
        if complement in num_to_index:
            count += num_to_index[complement]
        num_to_index[num] = num_to_index.get(num, 0) + 1
    return count
